-- Permission vocabulary and system roles of the geo module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the geo permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('city:create'::text, 'city'::text, 'create'::text, 'Create city'::text),
            ('city:delete'::text, 'city'::text, 'delete'::text, 'Delete city'::text),
            ('city:purge'::text, 'city'::text, 'purge'::text, 'Purge city'::text),
            ('city:restore'::text, 'city'::text, 'restore'::text, 'Restore city'::text),
            ('city:update'::text, 'city'::text, 'update'::text, 'Update city'::text),
            ('country:create'::text, 'country'::text, 'create'::text, 'Create country'::text),
            ('country:delete'::text, 'country'::text, 'delete'::text, 'Delete country'::text),
            ('country:purge'::text, 'country'::text, 'purge'::text, 'Purge country'::text),
            ('country:restore'::text, 'country'::text, 'restore'::text, 'Restore country'::text),
            ('country:update'::text, 'country'::text, 'update'::text, 'Update country'::text),
            ('district:create'::text, 'district'::text, 'create'::text, 'Create district'::text),
            ('district:delete'::text, 'district'::text, 'delete'::text, 'Delete district'::text),
            ('district:purge'::text, 'district'::text, 'purge'::text, 'Purge district'::text),
            ('district:restore'::text, 'district'::text, 'restore'::text, 'Restore district'::text),
            ('district:update'::text, 'district'::text, 'update'::text, 'Update district'::text),
            ('province:create'::text, 'province'::text, 'create'::text, 'Create province'::text),
            ('province:delete'::text, 'province'::text, 'delete'::text, 'Delete province'::text),
            ('province:purge'::text, 'province'::text, 'purge'::text, 'Purge province'::text),
            ('province:restore'::text, 'province'::text, 'restore'::text, 'Restore province'::text),
            ('province:update'::text, 'province'::text, 'update'::text, 'Update province'::text),
            ('subdistrict:create'::text, 'subdistrict'::text, 'create'::text, 'Create subdistrict'::text),
            ('subdistrict:delete'::text, 'subdistrict'::text, 'delete'::text, 'Delete subdistrict'::text),
            ('subdistrict:purge'::text, 'subdistrict'::text, 'purge'::text, 'Purge subdistrict'::text),
            ('subdistrict:restore'::text, 'subdistrict'::text, 'restore'::text, 'Restore subdistrict'::text),
            ('subdistrict:update'::text, 'subdistrict'::text, 'update'::text, 'Update subdistrict'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('city:create'::text, 'city'::text, 'create'::text, 'Create city'::text),
            ('city:delete'::text, 'city'::text, 'delete'::text, 'Delete city'::text),
            ('city:purge'::text, 'city'::text, 'purge'::text, 'Purge city'::text),
            ('city:restore'::text, 'city'::text, 'restore'::text, 'Restore city'::text),
            ('city:update'::text, 'city'::text, 'update'::text, 'Update city'::text),
            ('country:create'::text, 'country'::text, 'create'::text, 'Create country'::text),
            ('country:delete'::text, 'country'::text, 'delete'::text, 'Delete country'::text),
            ('country:purge'::text, 'country'::text, 'purge'::text, 'Purge country'::text),
            ('country:restore'::text, 'country'::text, 'restore'::text, 'Restore country'::text),
            ('country:update'::text, 'country'::text, 'update'::text, 'Update country'::text),
            ('district:create'::text, 'district'::text, 'create'::text, 'Create district'::text),
            ('district:delete'::text, 'district'::text, 'delete'::text, 'Delete district'::text),
            ('district:purge'::text, 'district'::text, 'purge'::text, 'Purge district'::text),
            ('district:restore'::text, 'district'::text, 'restore'::text, 'Restore district'::text),
            ('district:update'::text, 'district'::text, 'update'::text, 'Update district'::text),
            ('province:create'::text, 'province'::text, 'create'::text, 'Create province'::text),
            ('province:delete'::text, 'province'::text, 'delete'::text, 'Delete province'::text),
            ('province:purge'::text, 'province'::text, 'purge'::text, 'Purge province'::text),
            ('province:restore'::text, 'province'::text, 'restore'::text, 'Restore province'::text),
            ('province:update'::text, 'province'::text, 'update'::text, 'Update province'::text),
            ('subdistrict:create'::text, 'subdistrict'::text, 'create'::text, 'Create subdistrict'::text),
            ('subdistrict:delete'::text, 'subdistrict'::text, 'delete'::text, 'Delete subdistrict'::text),
            ('subdistrict:purge'::text, 'subdistrict'::text, 'purge'::text, 'Purge subdistrict'::text),
            ('subdistrict:restore'::text, 'subdistrict'::text, 'restore'::text, 'Restore subdistrict'::text),
            ('subdistrict:update'::text, 'subdistrict'::text, 'update'::text, 'Update subdistrict'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
